  // 126 hand-drawn maps

  // ---- Stone walls ('h' props) are real walls: a tile two levels above the ground beside it, with no slope, so only units that can climb 2 (jump 2) get on top. ----
  // The pass runs on every map here: it takes each wall tile out of the blocked list and sets its height to 2 above the highest open ground touching its wall run.
  (function wallsPass() {
    const nbrs = (x, y) => (y & 1) ? [[x+1,y-1],[x+1,y],[x+1,y+1],[x,y+1],[x-1,y],[x,y-1]] : [[x,y-1],[x+1,y],[x,y+1],[x-1,y+1],[x-1,y],[x-1,y-1]];
    for (const id in window.GAME_DATA.maps) {
      const m = window.GAME_DATA.maps[id], pr = m.props || {};
      const wall = new Set(Object.keys(pr).filter(k => pr[k] === 'h'));
      if (!wall.size || m.__walls) continue;
      m.__walls = true;
      const H = m.heights.length, W = m.heights[0].length, voids = new Set((m.voids || []).map(([x, y]) => x + ',' + y));
      const rockSet = new Set((m.rocks || []).map(r => Array.isArray(r) ? r.join(',') : r));
      const left = new Set(wall), seen = new Set();
      for (const k0 of wall) {
        if (seen.has(k0)) continue;
        const run = [], q = [k0]; seen.add(k0);
        while (q.length) { const k = q.pop(); run.push(k); const [x, y] = k.split(',').map(Number); for (const [a, b] of nbrs(x, y)) { const kk = a + ',' + b; if (wall.has(kk) && !seen.has(kk)) { seen.add(kk); q.push(kk) } } }
        let base = -1;
        for (const k of run) { const [x, y] = k.split(',').map(Number); for (const [a, b] of nbrs(x, y)) { const kk = a + ',' + b; if (a < 0 || b < 0 || a >= W || b >= H || wall.has(kk) || voids.has(kk) || rockSet.has(kk)) continue; base = Math.max(base, m.heights[b][a]) } }
        if (base < 0) base = 0;
        for (const k of run) { const [x, y] = k.split(',').map(Number); m.heights[y][x] = base + 2 }
      }
      m.rocks = (m.rocks || []).filter(r => !wall.has(Array.isArray(r) ? r.join(',') : r));
    }
  })();

  // Automatically picks a random map on page load.
  // Change 'random' to e.g. 'twin_cliffs' if you want to lock a specific map for testing.
  const selectedKey = 'random';
  const keys = Object.keys(window.GAME_DATA.maps).filter(k => !k.startsWith('dgm_') && !k.startsWith('road_')); // the page-load default is any hand-made field map
  const chosen = selectedKey === 'random'
    ? window.GAME_DATA.maps[keys[Math.floor(Math.random() * keys.length)]]
    : window.GAME_DATA.maps[selectedKey];

  if (window.GAME_DATA.combatRules && chosen) {
    Object.assign(window.GAME_DATA.combatRules.battlefield, chosen);
  }
